import datetime, json, os, pathlib, signal, stat, subprocess, sys, tempfile, time
from urllib.parse import urlsplit

op, *args = sys.argv[1:]
def bounded(path, limit, nofollow=True):
    flags = os.O_RDONLY | os.O_NONBLOCK
    if nofollow:
        flags |= os.O_NOFOLLOW
    fd = os.open(path, flags)
    with os.fdopen(fd, "rb") as f:
        metadata = os.fstat(f.fileno())
        if not stat.S_ISREG(metadata.st_mode):
            raise ValueError()
        data = f.read(limit + 1)
        if len(data) > limit or not os.path.samestat(metadata, os.stat(path, follow_symlinks=False)):
            raise ValueError()
        return data, metadata

def atomic(path, data):
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(path))
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
        os.replace(temporary, path)
    finally:
        if os.path.lexists(temporary):
            os.unlink(temporary)

try:
    if op == "clock":
        print(time.monotonic_ns() // 1_000_000)
    elif op == "supervise":
        term, grace, *command = args
        # This process retains the inherited lock while the command runs.
        for sig in (signal.SIGHUP, signal.SIGINT, signal.SIGTERM, signal.SIGPIPE):
            signal.signal(sig, lambda *_: None)
        child = subprocess.Popen(["timeout", "-k", grace, term, *command],
                                 start_new_session=True, close_fds=True)
        try:
            status = child.wait(timeout=float(term) + float(grace))
        except subprocess.TimeoutExpired:
            status = 124
        if status in (124, 137) or status < 0:
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        if child.poll() is None:
            try:
                child.wait(timeout=0.1)
            except subprocess.TimeoutExpired:
                pass
        sys.exit(128 - status if status < 0 else status)
    elif op == "capture":
        limit, *command = args
        with subprocess.Popen(command, stdout=subprocess.PIPE) as child:
            data = child.stdout.read(int(limit) + 1)
            if len(data) > int(limit):
                child.kill()
                sys.exit(125)
            sys.stdout.buffer.write(data)
            status = child.wait()
        sys.exit(128 - status if status < 0 else status)
    elif op == "lockfile":
        p, = args
        fd = os.open(p, os.O_WRONLY | os.O_APPEND | os.O_CREAT | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600)
        with os.fdopen(fd, "ab") as f:
            s = os.fstat(f.fileno())
            if not stat.S_ISREG(s.st_mode) or s.st_uid != 0 or stat.S_IMODE(s.st_mode) != 0o600:
                raise ValueError()
    elif op == "read":
        p, = args
        data, _ = bounded(p, 512)
        if not data.endswith(b"\n") or any(c < 32 or c > 126 for c in data[:-1]):
            raise ValueError()
        print(data[:-1].decode("ascii"))
    elif op == "mark":
        p, = args
        try:
            fd = os.open(p, os.O_CREAT | os.O_EXCL | os.O_WRONLY | os.O_NOFOLLOW, 0o600)
        except FileExistsError:
            pass
        else:
            os.close(fd)
        data, s = bounded(p, 0)
        if s.st_uid != 0 or stat.S_IMODE(s.st_mode) != 0o600:
            raise ValueError()
    elif op == "stage-record":
        directory, line = args
        fd, name = tempfile.mkstemp(dir=directory, prefix=".attempt.")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(line.encode("ascii") + b"\n")
        except BaseException:
            os.unlink(name)
            raise
        print(name)
    elif op == "stage":
        directory, = args
        with tempfile.NamedTemporaryFile(dir=directory, prefix=".deploy.", delete=False) as f:
            try:
                f.write(datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ\n").encode("ascii"))
                f.flush()
                os.fsync(f.fileno())
            except BaseException:
                os.unlink(f.name)
                raise
        print(f.name)
    elif op == "stamp":
        source, path = args
        if os.path.isdir(path):
            raise ValueError()
        os.replace(source, path)
        fd = os.open(os.path.dirname(path), os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    elif op == "marker":
        path, step, target, old = args
        data = json.dumps(dict(state="deploy_failed", timestamp=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                               step=step, target_sha=target, old_sha=old)).encode()
        atomic(path, data)
        if bounded(path, 4096)[0] != data:
            raise ValueError()
    elif op == "endpoint":
        path, = args
        prefix = "BTS_SCHEDULER_HEARTBEAT_PING_URL="
        lines = bounded(path, 65536)[0].decode().split("\n")
        value, = [line[len(prefix):] for line in lines if line.startswith(prefix)]
        if len(value) >= 2 and value[0] in (chr(34), chr(39)) and value[-1] == value[0]:
            value = value[1:-1]
        if any(c.isspace() or not c.isprintable() or c in (chr(34), chr(39), "\\", "?", "#") for c in value):
            raise ValueError()
        parsed = urlsplit(value)
        if parsed.scheme != "https" or not parsed.hostname or parsed.username is not None or parsed.password is not None:
            raise ValueError()
        if parsed.netloc.endswith(":"):
            raise ValueError()
        parsed.port
        print(value.rstrip("/") + "/fail")
    elif op == "cgroup":
        root, group = args
        if not os.path.isfile(os.path.join(root, "cgroup.controllers")):
            raise ValueError()
        if group:
            if not group.startswith("/") or ".." in pathlib.PurePosixPath(group).parts:
                raise ValueError()
            path = root + group
            try:
                events, _ = bounded(os.path.join(path, "cgroup.events"), 4096)
            except FileNotFoundError:
                if os.path.lexists(path):
                    raise
            else:
                if [line for line in events.splitlines() if line.startswith(b"populated ")] != [b"populated 0"]:
                    raise ValueError()
except FileNotFoundError:
    sys.exit(3 if op == "read" and not os.path.lexists(args[0]) else 1)
except Exception:
    sys.exit(1)

